import{_ as e,a,o as n,a6 as s}from"./chunks/framework.CJDy2q7X.js";const m=JSON.parse(`{"title":"Update Status (GraphQL)","description":"","frontmatter":{"outline":false,"examples":[{"id":"admin-return-update-status-gql","title":"Update Status","description":"Set the RMA status. \\"Received package\\" creates a refund for the returned item (send shipping to include shipping); \\"Item canceled\\" cancels the order item and restores inventory; any other status just updates the status. A status note is added and the customer is notified.","query":"mutation UpdateReturnStatus($input: updateStatusAdminReturnInput!) {\\n  updateStatusAdminReturn(input: $input) {\\n    adminReturn {\\n      id\\n      _id\\n      orderId\\n      orderIncrementId\\n      orderStatus\\n      customerName\\n      customerEmail\\n      isGuest\\n      statusId\\n      statusTitle\\n      statusColor\\n      packageCondition\\n      information\\n      canReopen\\n      item\\n      images\\n      availableStatuses\\n      messagesCount\\n      createdAt\\n      updatedAt\\n    }\\n  }\\n}\\n","variables":"{\\n  \\"input\\": {\\n    \\"id\\": \\"/api/admin/rma/requests/12\\",\\n    \\"rmaStatusId\\": 2,\\n    \\"shipping\\": 0\\n  }\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"updateStatusAdminReturn\\": {\\n      \\"adminReturn\\": {\\n        \\"id\\": \\"/api/admin/rma/requests/12\\",\\n        \\"_id\\": 12,\\n        \\"orderId\\": 45,\\n        \\"orderIncrementId\\": \\"000000045\\",\\n        \\"orderStatus\\": \\"processing\\",\\n        \\"customerName\\": \\"Jane Doe\\",\\n        \\"customerEmail\\": \\"jane@example.com\\",\\n        \\"isGuest\\": 0,\\n        \\"statusId\\": 2,\\n        \\"statusTitle\\": \\"Accept\\",\\n        \\"statusColor\\": \\"#12B76A\\",\\n        \\"packageCondition\\": \\"opened\\",\\n        \\"information\\": \\"Customer reported a defect.\\",\\n        \\"canReopen\\": false,\\n        \\"item\\": {\\n          \\"id\\": 30,\\n          \\"order_item_id\\": 78,\\n          \\"sku\\": \\"COASTALBREEZEMENSHOODIE\\",\\n          \\"name\\": \\"Coastal Breeze Men's Blue Zipper Hoodie\\",\\n          \\"quantity\\": 1,\\n          \\"resolution\\": \\"return\\",\\n          \\"reason_id\\": 2,\\n          \\"reason\\": \\"Damaged product\\",\\n          \\"variant_id\\": null\\n        },\\n        \\"images\\": [],\\n        \\"availableStatuses\\": [\\n          { \\"id\\": 5, \\"title\\": \\"Received package\\" },\\n          { \\"id\\": 4, \\"title\\": \\"Dispatched package\\" }\\n        ],\\n        \\"messagesCount\\": 3,\\n        \\"createdAt\\": \\"2026-07-20T10:15:30+00:00\\",\\n        \\"updatedAt\\": \\"2026-07-20T11:00:00+00:00\\"\\n      }\\n    }\\n  }\\n}\\n"}]},"headers":[],"relativePath":"api/graphql-api/admin/sales/returns/mutations/update-status.md","filePath":"api/graphql-api/admin/sales/returns/mutations/update-status.md","lastUpdated":1786429091000}`),d={name:"api/graphql-api/admin/sales/returns/mutations/update-status.md"};function r(i,t,o,u,c,p){return n(),a("div",null,t[0]||(t[0]=[s('<h1 id="update-status-graphql" tabindex="-1">Update Status (GraphQL) <a class="header-anchor" href="#update-status-graphql" aria-label="Permalink to &quot;Update Status (GraphQL)&quot;">​</a></h1><p>Moves an RMA request to a new status. Pass a status id taken from the request&#39;s <code>availableStatuses</code> (see <a href="./../queries/view-return.html">View Return</a>).</p><h2 id="action-semantics" tabindex="-1">Action semantics <a class="header-anchor" href="#action-semantics" aria-label="Permalink to &quot;Action semantics&quot;">​</a></h2><p>Two statuses do more than change the label:</p><ul><li><strong>Received package</strong> (<code>rmaStatusId</code> = <code>5</code>) — creates a <strong>refund</strong> for the returned item. Send a <code>shipping</code> amount to include shipping in the refund; omit or send <code>0</code> to refund the item only.</li><li><strong>Item canceled</strong> (<code>rmaStatusId</code> = <code>8</code>) — <strong>cancels the order item</strong> and restores its inventory.</li></ul><p>Any other status just updates the status. Every status change adds a note to the conversation and notifies the customer.</p><h2 id="input" tabindex="-1">Input <a class="header-anchor" href="#input" aria-label="Permalink to &quot;Input&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td><code>ID</code></td><td>yes</td><td>The return IRI (<code>/api/admin/rma/requests/{id}</code>).</td></tr><tr><td><code>rmaStatusId</code></td><td><code>Int</code></td><td>yes</td><td>The next status id (one of the request&#39;s <code>availableStatuses</code>).</td></tr><tr><td><code>shipping</code></td><td><code>Float</code></td><td>no</td><td>Shipping amount to include when the status creates a refund. Defaults to <code>0</code>.</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>See the <a href="/api/graphql-api/admin/sales/returns/">Returns overview</a> for the full status workflow.</p></div><p>Permission: <code>sales.rma.requests</code>.</p><p>All admin operations require an admin Bearer token — see <a href="/api/graphql-api/admin/authentication.html">Authentication</a>.</p>',11)]))}const h=e(d,[["render",r]]);export{m as __pageData,h as default};
